  VALUES
  ('781143a4-66b4-5e28-a9d5-4a2db5aca471', v_project, 'concept', 'Agency', $J$The capacity of persons or groups to act for reasons within the limits their circumstances set.$J$, NULL, '{"definition":"The capacity of persons or groups to act for reasons within the limits their circumstances set.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-agency","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('80e5794a-74bf-5c07-a435-71b6f6c7c0c7', v_project, 'concept', 'Communication', $J$The exchange of meaning between people through language, symbols and shared codes.$J$, NULL, '{"definition":"The exchange of meaning between people through language, symbols and shared codes.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-communication","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('80c35ee7-5781-55f6-9d3b-8e965f4f5618', v_project, 'concept', 'Conflict', $J$Competing interests or goals among individuals or groups in a shared setting.$J$, NULL, '{"definition":"Competing interests or goals among individuals or groups in a shared setting.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-conflict","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('d7094e85-8ed0-5b69-b6e3-5fcf954eb582', v_project, 'concept', 'Cooperation', $J$Coordinated action for mutual benefit, sustained by trust, norms, incentives or institutions.$J$, NULL, '{"definition":"Coordinated action for mutual benefit, sustained by trust, norms, incentives or institutions.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-cooperation","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('4d0aa77c-9673-5444-9a04-d490aab9f7fc', v_project, 'concept', 'Culture', $J$Knowledge, beliefs, practices and artifacts a group shares and passes on.$J$, NULL, '{"definition":"Knowledge, beliefs, practices and artifacts a group shares and passes on.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-culture","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('4e1ba9af-f7f2-5a32-b3c5-83baca7d1265', v_project, 'concept', 'Institutions', $J$Stable, recognized rules and structures that organize collective behaviour.$J$, NULL, '{"definition":"Stable, recognized rules and structures that organize collective behaviour.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-institutions","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('a6b63554-589c-5a94-b249-250d6adb41e9', v_project, 'concept', 'Knowledge', $J$Understanding that a group holds and justifies, such as shared records and expertise.$J$, NULL, '{"definition":"Understanding that a group holds and justifies, such as shared records and expertise.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-knowledge","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('380fb2a2-69bf-5950-9997-0b88e441278c', v_project, 'concept', 'Norms', $J$Shared expectations enforced by social approval and disapproval.$J$, NULL, '{"definition":"Shared expectations enforced by social approval and disapproval.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-norms","conceptbase_registered":false,"origin":"Interdisciplinary vocabulary, restricted to its sense in this domain","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('7172a165-29d6-5fb9-95e4-8e489b7bdec4', v_project, 'concept', 'Group', $J$People who see themselves, or are seen, as one body with shared interests or identity.$J$, NULL, '{"definition":"People who see themselves, or are seen, as one body with shared interests or identity.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-group","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('1b24284c-8f34-57b5-83bc-0b21e990d1e7', v_project, 'concept', 'Role', $J$A position in a group with expected behaviours and responsibilities.$J$, NULL, '{"definition":"A position in a group with expected behaviours and responsibilities.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-role","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('d9a7d40a-15a6-5d10-a17c-777b612924a0', v_project, 'concept', 'Incentive', $J$A benefit or cost that changes which choices look attractive.$J$, NULL, '{"definition":"A benefit or cost that changes which choices look attractive.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-incentive","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('da192735-7ddb-59aa-937b-4090a3073862', v_project, 'concept', 'Collective Action', $J$Action that needs many contributors, where individuals can gain without contributing.$J$, NULL, '{"definition":"Action that needs many contributors, where individuals can gain without contributing.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-collective-action","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('834c8631-d832-5ddc-81f8-828686900d33', v_project, 'concept', 'Power', $J$The capacity to affect others' options or outcomes, including through authority and resources.$J$, NULL, '{"definition":"The capacity to affect others'' options or outcomes, including through authority and resources.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-power","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('1c6776e1-7f70-52c2-8c93-00089fb0056c', v_project, 'concept', 'Diffusion', $J$The spread of an idea or practice through contact and adoption.$J$, NULL, '{"definition":"The spread of an idea or practice through contact and adoption.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-diffusion","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
  ('d221821a-01a1-54d7-a156-df38866a1dc5', v_project, 'concept', 'Social Change', $J$Change over time in a group's norms, institutions or practices.$J$, NULL, '{"definition":"Change over time in a group''s norms, institutions or practices.","vocabulary":"SOCIAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-social-core-social-change","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed')
  INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('067d4563-07b7-5c5c-8e9c-1dba9b610402', v_project, v_branch, 'strand', $J$Groups, Norms and Rules$J$, $J$The foundation strand. Students move from naming the groups they belong to and the rules those groups share, through roles and the reasons rules differ, to how norms are enforced and how formal institutions differ from informal norms. Explanations cite goals, rules, roles, incentives and power. They never borrow a mechanism from biology or computing.$J$, 'K-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-groups-norms-and-rules","description":"The foundation strand. Students move from naming the groups they belong to and the rules those groups share, through roles and the reasons rules differ, to how norms are enforced and how formal institutions differ from informal norms. Explanations cite goals, rules, roles, incentives and power. They never borrow a mechanism from biology or computing.","associatedDomains":["Social Studies"],"relations":{"foundationalTo":["OE-STRAND-social-core-cooperation-conflict-and-collective-action"]},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-THEORY-sociocultural-progression-as-community-practice"],"method":["OE-METHOD-role-play","OE-METHOD-controlled-dialogue","OE-METHOD-case-study-method"]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s1-groups-norms-and-rules.yaml"}}'::jsonb, 'accepted'),
  ('c4836b7e-c2ac-5eda-9368-08e410453278', v_project, v_branch, 'substrand', $J$Groups We Belong To and Their Rules$J$, $J$Key concepts: Group, Norms, Role$J$, 'K-2', 'Social Studies', '{"source_id":"OE-STRAND-social-core-groups-norms-and-rules-K-2","performanceIndicators":["Names at least three groups the child belongs to, such as family, class and a team.","Says what a rule in one of those groups asks people to do.","Gives an example of a rule that differs between two groups."],"concepts":[{"id":"OE-CONCEPT-social-core-group","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-norms","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-role","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-ostrom-1998","OE-LITERATURE-greene-2013","OE-LITERATURE-meng-2026","OE-LITERATURE-tomasello-2016","OE-LITERATURE-tomasello-2014-what-makes-us-human","OE-LITERATURE-muthukrishna-2020"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s1-groups-norms-and-rules.yaml"}}'::jsonb, 'accepted'),
  ('f21b382b-ed4a-5e4e-b69b-d603834fbbe9', v_project, v_branch, 'substrand', $J$Roles and Why Rules Differ$J$, $J$Key concepts: Role, Group, Norms, Culture$J$, '3-5', 'Social Studies', '{"source_id":"OE-STRAND-social-core-groups-norms-and-rules-3-5","performanceIndicators":["Describes the role of a person in two different groups and what each group expects of that person.","Explains one reason a rule differs between two groups, such as purpose, history or size.","Tells a rule written down from a custom people follow without being told."],"concepts":[{"id":"OE-CONCEPT-social-core-role","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-group","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-norms","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-culture","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-social-core-cooperation-conflict-and-collective-action-3-5"]},"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-ostrom-1998","OE-LITERATURE-greene-2013","OE-LITERATURE-meng-2026","OE-LITERATURE-tomasello-2016","OE-LITERATURE-tomasello-2014-what-makes-us-human","OE-LITERATURE-muthukrishna-2020"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s1-groups-norms-and-rules.yaml"}}'::jsonb, 'accepted'),
  ('9ef944f3-b11a-5327-9082-b53ba736a834', v_project, v_branch, 'substrand', $J$How Norms Are Enforced$J$, $J$Key concepts: Norms, Incentive, Institutions, Power$J$, '6-8', 'Social Studies', '{"source_id":"OE-STRAND-social-core-groups-norms-and-rules-6-8","performanceIndicators":["Explains how approval and disapproval keep a norm in place in a named case.","Tells a norm enforced by peers from a rule enforced by an authority.","Predicts what happens to a norm when enforcement stops, and says what evidence would test the prediction."],"concepts":[{"id":"OE-CONCEPT-social-core-norms","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-incentive","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-institutions","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-power","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-social-core-cooperation-conflict-and-collective-action-6-8"]},"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-ostrom-1998","OE-LITERATURE-greene-2013","OE-LITERATURE-meng-2026","OE-LITERATURE-tomasello-2016","OE-LITERATURE-tomasello-2014-what-makes-us-human","OE-LITERATURE-muthukrishna-2020"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s1-groups-norms-and-rules.yaml"}}'::jsonb, 'accepted'),
  ('56eb4828-57c2-589b-92ba-180f901b2443', v_project, v_branch, 'substrand', $J$Formal Institutions and Informal Norms$J$, $J$Key concepts: Institutions, Norms, Incentive, Power, Agency$J$, '9-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-groups-norms-and-rules-9-12","performanceIndicators":["Sorts the constraints in a case into formal institutions and informal norms and justifies each placement.","Traces how an institution changes the incentives people face.","Compares how the same aim is pursued under two different institutions."],"concepts":[{"id":"OE-CONCEPT-social-core-institutions","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-norms","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-incentive","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-power","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-agency","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-social-core-cooperation-conflict-and-collective-action-9-12","OE-STRAND-social-core-social-change-and-diversity-of-societies-9-12"]},"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-ostrom-1998","OE-LITERATURE-greene-2013","OE-LITERATURE-meng-2026","OE-LITERATURE-tomasello-2016","OE-LITERATURE-tomasello-2014-what-makes-us-human","OE-LITERATURE-muthukrishna-2020"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s1-groups-norms-and-rules.yaml"}}'::jsonb, 'accepted'),
  ('1d8ecb11-c3b4-57b0-9a0f-b32667147fea', v_project, v_branch, 'strand', $J$Cooperation, Conflict and Collective Action$J$, $J$The central strand. Students move from sharing and taking turns, through why people cooperate or hold back, to shared-resource problems where individuals can gain without contributing, and finally to comparing designs for governing shared resources and judging the part power and conflict play in each.$J$, 'K-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-cooperation-conflict-and-collective-action","description":"The central strand. Students move from sharing and taking turns, through why people cooperate or hold back, to shared-resource problems where individuals can gain without contributing, and finally to comparing designs for governing shared resources and judging the part power and conflict play in each.","associatedDomains":["Social Studies"],"relations":{},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-THEORY-core-design-principles-for-cooperation","OE-PROPOSITION-nine-conditions-for-group-cooperation","OE-PROPOSITION-commons-dilemma-misaligned-interests"],"method":["OE-METHOD-public-goods-game","OE-METHOD-dictator-game","OE-METHOD-ultimatum-game","OE-METHOD-pro-con-debate","OE-METHOD-teaching-evolution-cooperation-primary"]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s2-cooperation-conflict-and-collective-action.yaml"}}'::jsonb, 'accepted'),
  ('f7608bc0-18ff-52e5-8238-ac0220214ec9', v_project, v_branch, 'substrand', $J$Sharing and Taking Turns$J$, $J$Key concepts: Cooperation, Conflict, Norms, Communication$J$, 'K-2', 'Social Studies', '{"source_id":"OE-STRAND-social-core-cooperation-conflict-and-collective-action-K-2","performanceIndicators":["Takes turns in a simple game and says why turns are fair.","Says what happens to a group when one member does not share.","Names one way a group can fix an unfair turn."],"concepts":[{"id":"OE-CONCEPT-social-core-cooperation","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-conflict","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-norms","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-communication","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-basurto-ostrom-2009","OE-LITERATURE-ostrom-2009-ses-framework","OE-LITERATURE-koomen-herrmann-2018","OE-LITERATURE-leighton-2014","OE-LITERATURE-wilson-ostrom-cox-2013","OE-LITERATURE-richerson-2016"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s2-cooperation-conflict-and-collective-action.yaml"}}'::jsonb, 'accepted'),
  ('3d964122-338c-548e-882b-d833d2ec4209', v_project, v_branch, 'substrand', $J$Why People Cooperate or Hold Back$J$, $J$Key concepts: Cooperation, Incentive, Communication, Conflict$J$, '3-5', 'Social Studies', '{"source_id":"OE-STRAND-social-core-cooperation-conflict-and-collective-action-3-5","performanceIndicators":["Explains in a game or a story why a person gives or keeps.","Names an incentive and a form of trust that support cooperation.","Describes how talking together changes whether people cooperate."],"concepts":[{"id":"OE-CONCEPT-social-core-cooperation","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-incentive","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-communication","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-conflict","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-basurto-ostrom-2009","OE-LITERATURE-ostrom-2009-ses-framework","OE-LITERATURE-koomen-herrmann-2018","OE-LITERATURE-leighton-2014","OE-LITERATURE-wilson-ostrom-cox-2013","OE-LITERATURE-richerson-2016"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s2-cooperation-conflict-and-collective-action.yaml"}}'::jsonb, 'accepted'),
  ('2de4fac1-1590-5260-a501-d040c57c2acf', v_project, v_branch, 'substrand', $J$Shared-Resource Problems$J$, $J$Key concepts: Collective Action, Incentive, Cooperation, Conflict, Norms$J$, '6-8', 'Social Studies', '{"source_id":"OE-STRAND-social-core-cooperation-conflict-and-collective-action-6-8","performanceIndicators":["Describes a shared-resource problem and who gains and who loses when someone does not contribute.","Explains why each person''s best choice can leave the group worse off.","Proposes two ways a group could reduce the problem and says what each costs."],"concepts":[{"id":"OE-CONCEPT-social-core-collective-action","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-incentive","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-cooperation","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-conflict","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-norms","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-social-core-groups-norms-and-rules-9-12"]},"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-basurto-ostrom-2009","OE-LITERATURE-ostrom-2009-ses-framework","OE-LITERATURE-koomen-herrmann-2018","OE-LITERATURE-leighton-2014","OE-LITERATURE-wilson-ostrom-cox-2013","OE-LITERATURE-richerson-2016"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s2-cooperation-conflict-and-collective-action.yaml"}}'::jsonb, 'accepted'),
  ('e0e725b5-1716-5f38-95d7-bdaa1297f892', v_project, v_branch, 'substrand', $J$Governing Shared Resources: Power and Conflict$J$, $J$Key concepts: Collective Action, Power, Conflict, Institutions, Cooperation$J$, '9-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-cooperation-conflict-and-collective-action-9-12","performanceIndicators":["Compares two designs for governing a shared resource on who decides, who monitors and how breaches are handled.","Judges how power and conflict shape which design a group ends up with.","Says what evidence from cases would favour one design over another."],"concepts":[{"id":"OE-CONCEPT-social-core-collective-action","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-power","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-conflict","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-institutions","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-cooperation","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-social-core-social-change-and-diversity-of-societies-9-12"]},"literature_ids":["OE-LITERATURE-ostrom-1990","OE-LITERATURE-basurto-ostrom-2009","OE-LITERATURE-ostrom-2009-ses-framework","OE-LITERATURE-koomen-herrmann-2018","OE-LITERATURE-leighton-2014","OE-LITERATURE-wilson-ostrom-cox-2013","OE-LITERATURE-richerson-2016"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s2-cooperation-conflict-and-collective-action.yaml"}}'::jsonb, 'accepted'),
  ('925d0b84-162d-5a26-a26c-c15db8863af1', v_project, v_branch, 'strand', $J$Social Change and Diversity of Societies$J$, $J$The macro strand. Students compare communities then and now, trace how a practice spread from one community to another, explain why societies differ using geography, history and institutions, and evaluate explanations of large-scale change. It is the weakest strand for grounding: the corpus holds no native social-science source for it, and the sources it has are bridge sources used as contrast cases.$J$, 'K-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-social-change-and-diversity-of-societies","description":"The macro strand. Students compare communities then and now, trace how a practice spread from one community to another, explain why societies differ using geography, history and institutions, and evaluate explanations of large-scale change. It is the weakest strand for grounding: the corpus holds no native social-science source for it, and the sources it has are bridge sources used as contrast cases.","associatedDomains":["Social Studies"],"relations":{},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-ASSUMPTION-cultural-evolution-nos-profile-differs-from-biological-evolution"],"method":["OE-METHOD-causal-mapping","OE-METHOD-case-study-method"]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s3-social-change-and-diversity-of-societies.yaml"}}'::jsonb, 'accepted'),
  ('ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', v_project, v_branch, 'substrand', $J$Communities Then and Now$J$, $J$Key concepts: Social Change, Culture, Group$J$, 'K-2', 'Social Studies', '{"source_id":"OE-STRAND-social-core-social-change-and-diversity-of-societies-K-2","performanceIndicators":["Names two things that are different in a community now compared with long ago.","Asks an older person what changed.","Says one reason a change happened."],"concepts":[{"id":"OE-CONCEPT-social-core-social-change","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-group","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-mesoudi-2011","OE-LITERATURE-cultural-evolution-society-2023","OE-LITERATURE-schimmelpfennig-muthukrishna-2023-cultural-evolutionary-behavioural-science","OE-LITERATURE-waring-et-al-2015","OE-LITERATURE-tehrani-2011"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s3-social-change-and-diversity-of-societies.yaml"}}'::jsonb, 'accepted'),
  ('aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', v_project, v_branch, 'substrand', $J$How a Practice Spreads$J$, $J$Key concepts: Diffusion, Knowledge, Culture, Communication$J$, '3-5', 'Social Studies', '{"source_id":"OE-STRAND-social-core-social-change-and-diversity-of-societies-3-5","performanceIndicators":["Traces a practice such as a food, a tool, a game or a custom from where it began to where it is now.","Names the contact that carried it from one community to another.","Explains why one community adopted it and another did not."],"concepts":[{"id":"OE-CONCEPT-social-core-diffusion","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-knowledge","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-culture","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-communication","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-mesoudi-2011","OE-LITERATURE-cultural-evolution-society-2023","OE-LITERATURE-schimmelpfennig-muthukrishna-2023-cultural-evolutionary-behavioural-science","OE-LITERATURE-waring-et-al-2015","OE-LITERATURE-tehrani-2011"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s3-social-change-and-diversity-of-societies.yaml"}}'::jsonb, 'accepted'),
  ('fd772a6a-0dd8-5410-96c5-79f75443183c', v_project, v_branch, 'substrand', $J$Why Societies Differ$J$, $J$Key concepts: Culture, Institutions, Social Change, Knowledge$J$, '6-8', 'Social Studies', '{"source_id":"OE-STRAND-social-core-social-change-and-diversity-of-societies-6-8","performanceIndicators":["Explains a difference between two societies using geography, history and institutions, and names the evidence.","Says where one cause alone fails to explain the difference.","Compares how two societies handle the same problem."],"concepts":[{"id":"OE-CONCEPT-social-core-culture","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-institutions","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-social-change","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-knowledge","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-mesoudi-2011","OE-LITERATURE-cultural-evolution-society-2023","OE-LITERATURE-schimmelpfennig-muthukrishna-2023-cultural-evolutionary-behavioural-science","OE-LITERATURE-waring-et-al-2015","OE-LITERATURE-tehrani-2011"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s3-social-change-and-diversity-of-societies.yaml"}}'::jsonb, 'accepted'),
  ('504c7645-bc71-5a81-a114-cd2d598d1621', v_project, v_branch, 'substrand', $J$Explaining Large-Scale Change$J$, $J$Key concepts: Social Change, Agency, Power, Institutions, Knowledge, Diffusion$J$, '9-12', 'Social Studies', '{"source_id":"OE-STRAND-social-core-social-change-and-diversity-of-societies-9-12","performanceIndicators":["Evaluates two explanations of a large-scale change against the same evidence.","Identifies where a single-cause account fails.","Explains how agency, power and institutions interact in a change over generations."],"concepts":[{"id":"OE-CONCEPT-social-core-social-change","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-agency","emphasis":"primary"},{"id":"OE-CONCEPT-social-core-power","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-institutions","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-knowledge","emphasis":"reinforcing"},{"id":"OE-CONCEPT-social-core-diffusion","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-mesoudi-2011","OE-LITERATURE-cultural-evolution-society-2023","OE-LITERATURE-schimmelpfennig-muthukrishna-2023-cultural-evolutionary-behavioural-science","OE-LITERATURE-waring-et-al-2015","OE-LITERATURE-tehrani-2011"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"social-core-draft-2026-10-25","path":"strands/strand-s3-social-change-and-diversity-of-societies.yaml"}}'::jsonb, 'accepted')
