  (v_project, 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', '3d964122-338c-548e-882b-d833d2ec4209', 'prerequisiteOf', 'asserted', $J$Roles and the reasons rules differ come before explaining why people cooperate or hold back inside a group.$J$, 'accepted'),
  (v_project, '9ef944f3-b11a-5327-9082-b53ba736a834', '2de4fac1-1590-5260-a501-d040c57c2acf', 'prerequisiteOf', 'asserted', $J$How norms are enforced comes before analysing a shared-resource problem, where enforcement is the open question.$J$, 'accepted'),
  (v_project, '2de4fac1-1590-5260-a501-d040c57c2acf', '56eb4828-57c2-589b-92ba-180f901b2443', 'prerequisiteOf', 'asserted', $J$The shared-resource problem is what motivates the formal institutions the 9-12 stage compares with informal norms. The dependency runs from the central strand back into the foundation strand.$J$, 'accepted'),
  (v_project, '56eb4828-57c2-589b-92ba-180f901b2443', 'e0e725b5-1716-5f38-95d7-bdaa1297f892', 'prerequisiteOf', 'asserted', $J$Comparing designs for governing a shared resource needs the distinction between formal institutions and informal norms.$J$, 'accepted'),
  (v_project, '56eb4828-57c2-589b-92ba-180f901b2443', '504c7645-bc71-5a81-a114-cd2d598d1621', 'prerequisiteOf', 'asserted', $J$Judging large-scale explanations of change needs institutions as a named cause.$J$, 'accepted'),
