  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, status)
  VALUES
  ('22b630dd-a493-5e6c-a494-ef502bac8b81', v_project, v_branch, 'groups-norms-and-rules', $J$Groups, Norms and Rules$J$, 'vertical', $J$People live in groups, and groups hold rules and expectations that shape what members do. The strand builds from naming groups to telling formal institutions from informal norms.$J$, $J$The foundation strand. Students move from naming the groups they belong to and the rules those groups share, through roles and the reasons rules differ, to how norms are enforced and how formal institutions differ from informal norms. Explanations cite goals, rules, roles, incentives and power. They never borrow a mechanism from biology or computing.$J$, 'accepted'),
  ('87fc0d64-1249-516d-b033-ed2b04df854d', v_project, v_branch, 'cooperation-conflict-and-collective-action', $J$Cooperation, Conflict and Collective Action$J$, 'vertical', $J$People cooperate when incentives, trust, norms and institutions make it worth doing, and shared-resource problems show where cooperation fails and what groups do about it.$J$, $J$The central strand. Students move from sharing and taking turns, through why people cooperate or hold back, to shared-resource problems where individuals can gain without contributing, and finally to comparing designs for governing shared resources and judging the part power and conflict play in each.$J$, 'accepted'),
  ('9ec5a9a9-3858-5f28-b222-91c7c79808f2', v_project, v_branch, 'social-change-and-diversity-of-societies', $J$Social Change and Diversity of Societies$J$, 'vertical', $J$Societies change and differ, and explaining either takes more than one cause. The strand builds from comparing communities across time to judging large-scale explanations of change.$J$, $J$The macro strand. Students compare communities then and now, trace how a practice spread from one community to another, explain why societies differ using geography, history and institutions, and evaluate explanations of large-scale change. It is the weakest strand for grounding: the corpus holds no native social-science source for it, and the sources it has are bridge sources used as contrast cases.$J$, 'accepted')
  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, relation_to_next)
  VALUES
  ('2f0fe8fc-b0a0-5912-915a-a7072a492441', '22b630dd-a493-5e6c-a494-ef502bac8b81', 'c4836b7e-c2ac-5eda-9368-08e410453278', 1, $J$K-2, Groups We Belong To and Their Rules. Key concepts: Group, Norms, Role.$J$, $J$Leads into Roles and Why Rules Differ (3-5).$J$),
