  ('e49e585b-b47d-553f-adff-0381568f4589', v_project, 'concept', 'Data', $J$Recorded values or symbols that stand for something.$J$, NULL, '{"definition":"Recorded values or symbols that stand for something.","vocabulary":"COMPUTATIONAL-CORE-v0.1.0-draft","conceptbase_id":"OE-CONCEPT-computational-core-data","conceptbase_registered":false,"origin":"New in this space","draft_note":"AI-drafted 2026-10-25. No expert has reviewed this definition."}'::jsonb, 'proposed'),
