  INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status)
  VALUES
  ('37a89183-dce2-506d-a724-968c6ec03d06', v_project, v_branch, 'strand', $J$Data and Representation$J$, $J$The foundation strand. Students move from sorting and labelling things and learning that symbols stand for things, through recording and charting data and encoding text, images and numbers in binary, to the relation between information, compression and the limits of any representation.$J$, 'K-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-data-and-representation","description":"The foundation strand. Students move from sorting and labelling things and learning that symbols stand for things, through recording and charting data and encoding text, images and numbers in binary, to the relation between information, compression and the limits of any representation.","associatedDomains":["Computer Science"],"relations":{},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-CROSSDOMAINCONSTRUCT-information-processing-domain-general"],"competency":["OE-COMPETENCY-openevo-core-competencies-ct"],"method":[]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c1-data-and-representation.yaml"}}'::jsonb, 'accepted'),
  ('528aba11-45e9-5ec4-b5da-4ddf071ff6a2', v_project, v_branch, 'substrand', $J$Sorting, Labelling and Symbols$J$, $J$Key concepts: Data, Representation, Abstraction$J$, 'K-2', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-data-and-representation-K-2","performanceIndicators":["Sorts a set of objects by one property and says which property was used.","Labels each group with a word or a picture.","Says what a symbol such as an arrow, an icon or a letter stands for."],"concepts":[{"id":"OE-CONCEPT-computational-core-data","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-representation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-wing-2008","OE-LITERATURE-shannon-1948","OE-LITERATURE-weintrop-2016","OE-LITERATURE-denning-tedre-2019","OE-LITERATURE-grover-pea-2013","OE-LITERATURE-kirby-tamariz-cornish-smith-2015","OE-LITERATURE-arnon-kirby-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c1-data-and-representation.yaml"}}'::jsonb, 'accepted'),
  ('f95b2dff-2e43-597e-b8c6-a1857c0f60c7', v_project, v_branch, 'substrand', $J$Recording and Charting Data$J$, $J$Key concepts: Data, Representation, Information, Abstraction$J$, '3-5', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-data-and-representation-3-5","performanceIndicators":["Records measurements in a table.","Charts the data and describes a pattern in it.","Says what the chart leaves out."],"concepts":[{"id":"OE-CONCEPT-computational-core-data","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-representation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-information","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-computational-core-systems-models-and-learning-from-data-3-5"]},"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-wing-2008","OE-LITERATURE-shannon-1948","OE-LITERATURE-weintrop-2016","OE-LITERATURE-denning-tedre-2019","OE-LITERATURE-grover-pea-2013","OE-LITERATURE-kirby-tamariz-cornish-smith-2015","OE-LITERATURE-arnon-kirby-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c1-data-and-representation.yaml"}}'::jsonb, 'accepted'),
  ('f63a89a8-8a27-5cd6-acdf-7ed9f179442b', v_project, v_branch, 'substrand', $J$Encoding Text, Images and Numbers$J$, $J$Key concepts: Representation, Data, Information, Abstraction, Specification$J$, '6-8', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-data-and-representation-6-8","performanceIndicators":["Encodes a short text and a small image in binary using a stated scheme.","Compares two encodings of the same data on size and on the detail they keep.","Explains why a decoder needs to know the scheme."],"concepts":[{"id":"OE-CONCEPT-computational-core-representation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-data","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-information","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-specification","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-wing-2008","OE-LITERATURE-shannon-1948","OE-LITERATURE-weintrop-2016","OE-LITERATURE-denning-tedre-2019","OE-LITERATURE-grover-pea-2013","OE-LITERATURE-kirby-tamariz-cornish-smith-2015","OE-LITERATURE-arnon-kirby-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c1-data-and-representation.yaml"}}'::jsonb, 'accepted'),
  ('22e68923-d1f7-54a7-9cb5-6a3591c04a02', v_project, v_branch, 'substrand', $J$Information, Compression and the Limits of Representation$J$, $J$Key concepts: Information, Representation, Data, Abstraction$J$, '9-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-data-and-representation-9-12","performanceIndicators":["Relates the information in a message to how far it can be compressed, using bits.","Explains a case where compression loses detail and says what was lost.","Names a limit of a representation, such as precision, size or ambiguity, and the effect on a result."],"concepts":[{"id":"OE-CONCEPT-computational-core-information","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-representation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-data","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-computational-core-systems-models-and-learning-from-data-9-12"]},"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-wing-2008","OE-LITERATURE-shannon-1948","OE-LITERATURE-weintrop-2016","OE-LITERATURE-denning-tedre-2019","OE-LITERATURE-grover-pea-2013","OE-LITERATURE-kirby-tamariz-cornish-smith-2015","OE-LITERATURE-arnon-kirby-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c1-data-and-representation.yaml"}}'::jsonb, 'accepted'),
  ('7d846794-560b-58b9-a9f0-267a680c308d', v_project, v_branch, 'strand', $J$Algorithms and Programs$J$, $J$The central strand. Students move from following and writing step-by-step instructions, through programs with sequences, loops and conditions, to decomposing problems, writing functions and testing against a specification, and finally arguing for an algorithm's correctness and comparing its efficiency with another.$J$, 'K-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-algorithms-and-programs","description":"The central strand. Students move from following and writing step-by-step instructions, through programs with sequences, loops and conditions, to decomposing problems, writing functions and testing against a specification, and finally arguing for an algorithm''s correctness and comparing its efficiency with another.","associatedDomains":["Computer Science"],"relations":{"foundationalTo":["OE-STRAND-computational-core-systems-models-and-learning-from-data"]},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-CROSSDOMAINCONSTRUCT-computational-thinking-domain-generality"],"competency":["OE-COMPETENCY-openevo-core-competencies-ct"],"method":[]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c2-algorithms-and-programs.yaml"}}'::jsonb, 'accepted'),
  ('bd2869a3-e2d1-58c1-9878-0c17f2a21c68', v_project, v_branch, 'substrand', $J$Following and Writing Steps$J$, $J$Key concepts: Algorithm, Program$J$, 'K-2', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-algorithms-and-programs-K-2","performanceIndicators":["Follows a sequence of steps to complete a task.","Writes steps another child can follow and fixes a step that fails.","Says why the order of steps matters."],"concepts":[{"id":"OE-CONCEPT-computational-core-algorithm","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-program","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-brennan-resnick-2012","OE-LITERATURE-lye-koh-2014","OE-LITERATURE-barr-stephenson-2011","OE-LITERATURE-shute-2017","OE-LITERATURE-denning-2017","OE-LITERATURE-roman-gonzalez-2017","OE-LITERATURE-peel-sadler-friedrichsen-2019","OE-LITERATURE-peel-sadler-friedrichsen-2021","OE-LITERATURE-peel-sadler-friedrichsen-2025","OE-LITERATURE-christensen-lombardi-2023","OE-LITERATURE-christensen-lombardi-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c2-algorithms-and-programs.yaml"}}'::jsonb, 'accepted'),
