  ('31f4c2e2-f909-5cf1-ae61-ca82e22bda0e', v_project, v_branch, 'substrand', $J$Decomposition, Functions and Testing$J$, $J$Key concepts: Decomposition, Specification, Program, Abstraction, State$J$, '6-8', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-algorithms-and-programs-6-8","performanceIndicators":["Splits a problem into parts and writes a function for each part.","Writes test cases from a stated specification.","Explains when a program meets the specification and when a test shows that it does not."],"concepts":[{"id":"OE-CONCEPT-computational-core-decomposition","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-specification","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-program","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-state","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-computational-core-systems-models-and-learning-from-data-6-8"]},"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-brennan-resnick-2012","OE-LITERATURE-lye-koh-2014","OE-LITERATURE-barr-stephenson-2011","OE-LITERATURE-shute-2017","OE-LITERATURE-denning-2017","OE-LITERATURE-roman-gonzalez-2017","OE-LITERATURE-peel-sadler-friedrichsen-2019","OE-LITERATURE-peel-sadler-friedrichsen-2021","OE-LITERATURE-peel-sadler-friedrichsen-2025","OE-LITERATURE-christensen-lombardi-2023","OE-LITERATURE-christensen-lombardi-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c2-algorithms-and-programs.yaml"}}'::jsonb, 'accepted'),
  ('06ca57c6-f90e-5354-84b4-ee88dd292147', v_project, v_branch, 'substrand', $J$Correctness and Efficiency$J$, $J$Key concepts: Algorithm, Specification, Abstraction, State$J$, '9-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-algorithms-and-programs-9-12","performanceIndicators":["Argues why an algorithm gives the right output for all valid inputs.","Compares two algorithms for the same task on the steps they take as the input grows.","Chooses between them for a stated need and justifies the choice."],"concepts":[{"id":"OE-CONCEPT-computational-core-algorithm","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-specification","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-abstraction","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-state","emphasis":"reinforcing"}],"required":true,"relations":{"prerequisiteOf":["OE-STRAND-computational-core-systems-models-and-learning-from-data-9-12"]},"literature_ids":["OE-LITERATURE-wing-2006","OE-LITERATURE-brennan-resnick-2012","OE-LITERATURE-lye-koh-2014","OE-LITERATURE-barr-stephenson-2011","OE-LITERATURE-shute-2017","OE-LITERATURE-denning-2017","OE-LITERATURE-roman-gonzalez-2017","OE-LITERATURE-peel-sadler-friedrichsen-2019","OE-LITERATURE-peel-sadler-friedrichsen-2021","OE-LITERATURE-peel-sadler-friedrichsen-2025","OE-LITERATURE-christensen-lombardi-2023","OE-LITERATURE-christensen-lombardi-2024"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c2-algorithms-and-programs.yaml"}}'::jsonb, 'accepted'),
  ('a652b045-d46e-5ad9-acfe-052eea355407', v_project, v_branch, 'strand', $J$Systems, Models and Learning from Data$J$, $J$The macro strand. Students learn that machines follow rules people write, build simple models and simulations of everyday systems, build agent-based and feedback models where many simple rules produce one pattern, and compare machine learning, search and distributed systems. Its grounding is the strongest of the three strands in the corpus and its standards backing for search is the weakest.$J$, 'K-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-systems-models-and-learning-from-data","description":"The macro strand. Students learn that machines follow rules people write, build simple models and simulations of everyday systems, build agent-based and feedback models where many simple rules produce one pattern, and compare machine learning, search and distributed systems. Its grounding is the strongest of the three strands in the corpus and its standards backing for search is the weakest.","associatedDomains":["Computer Science"],"relations":{},"epistemicStatus":"designed-thought-experiment","anchors":{"theory":["OE-THEORY-restructuration-theory","OE-THEORY-computational-models-as-theory-mediators","OE-THEORY-critical-ai-literacies"],"competency":["OE-COMPETENCY-ai4k12-4-d-i-k-2-eu","OE-COMPETENCY-ai4k12-4-d-i-9-12-lo"],"method":["OE-METHOD-agent-based-modeling-netlogo","OE-METHOD-odd-protocol-model-description","OE-METHOD-causal-mapping"]},"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c3-systems-models-and-learning-from-data.yaml"}}'::jsonb, 'accepted'),
  ('04edbe9b-292d-5101-a009-fc46ead81427', v_project, v_branch, 'substrand', $J$Machines Follow Rules People Write$J$, $J$Key concepts: Program, Algorithm$J$, 'K-2', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-systems-models-and-learning-from-data-K-2","performanceIndicators":["Gives an example of a machine doing exactly what its instructions say.","Says what happens when the instructions are wrong.","Says who wrote the rules the machine follows."],"concepts":[{"id":"OE-CONCEPT-computational-core-program","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-algorithm","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wilensky-2020","OE-LITERATURE-tullis-goldstone-2017","OE-LITERATURE-grimm-etal-2020-odd","OE-LITERATURE-guest-2026-models","OE-LITERATURE-guest-martin-vanrooij-2026","OE-LITERATURE-guest-suarez-vanrooij-2025-cail","OE-LITERATURE-shiffrin-mitchell-2023","OE-LITERATURE-binz-schulz-2023","OE-LITERATURE-anwarzai-2026","OE-LITERATURE-falandays-2023","OE-LITERATURE-rahwan-2019-machine-behaviour","OE-LITERATURE-watson-szathmary-2016","OE-LITERATURE-kosal-2026"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c3-systems-models-and-learning-from-data.yaml"}}'::jsonb, 'accepted'),
  ('71bc5265-fbcd-5e5a-b093-399a24bce44d', v_project, v_branch, 'substrand', $J$Models and Simulations of Everyday Systems$J$, $J$Key concepts: Model, Simulation, State, Data$J$, '3-5', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-systems-models-and-learning-from-data-3-5","performanceIndicators":["Builds a model of an everyday system such as a pond, a queue or a traffic light, with a few named parts.","Runs the simulation and records what happens over time.","Says one thing the model leaves out."],"concepts":[{"id":"OE-CONCEPT-computational-core-model","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-simulation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-state","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-data","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wilensky-2020","OE-LITERATURE-tullis-goldstone-2017","OE-LITERATURE-grimm-etal-2020-odd","OE-LITERATURE-guest-2026-models","OE-LITERATURE-guest-martin-vanrooij-2026","OE-LITERATURE-guest-suarez-vanrooij-2025-cail","OE-LITERATURE-shiffrin-mitchell-2023","OE-LITERATURE-binz-schulz-2023","OE-LITERATURE-anwarzai-2026","OE-LITERATURE-falandays-2023","OE-LITERATURE-rahwan-2019-machine-behaviour","OE-LITERATURE-watson-szathmary-2016","OE-LITERATURE-kosal-2026"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c3-systems-models-and-learning-from-data.yaml"}}'::jsonb, 'accepted'),
  ('45c484c9-e753-5bb3-86af-086bc28fce31', v_project, v_branch, 'substrand', $J$Agent-Based and Feedback Models$J$, $J$Key concepts: Model, Simulation, Feedback, State, Distributed System$J$, '6-8', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-systems-models-and-learning-from-data-6-8","performanceIndicators":["Builds an agent-based model in which many agents follow the same simple rules.","Identifies a feedback loop in the model and shows its effect on the output.","Changes one rule and reports how the pattern changes."],"concepts":[{"id":"OE-CONCEPT-computational-core-model","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-simulation","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-feedback","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-state","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-distributed-system","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wilensky-2020","OE-LITERATURE-tullis-goldstone-2017","OE-LITERATURE-grimm-etal-2020-odd","OE-LITERATURE-guest-2026-models","OE-LITERATURE-guest-martin-vanrooij-2026","OE-LITERATURE-guest-suarez-vanrooij-2025-cail","OE-LITERATURE-shiffrin-mitchell-2023","OE-LITERATURE-binz-schulz-2023","OE-LITERATURE-anwarzai-2026","OE-LITERATURE-falandays-2023","OE-LITERATURE-rahwan-2019-machine-behaviour","OE-LITERATURE-watson-szathmary-2016","OE-LITERATURE-kosal-2026"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c3-systems-models-and-learning-from-data.yaml"}}'::jsonb, 'accepted'),
  ('e6374470-9533-570e-8d98-0e5b24060f4d', v_project, v_branch, 'substrand', $J$Machine Learning, Search and Distributed Systems Compared$J$, $J$Key concepts: Machine Learning, Search, Distributed System, Model, Feedback, Data$J$, '9-12', 'Computer Science', '{"source_id":"OE-STRAND-computational-core-systems-models-and-learning-from-data-9-12","performanceIndicators":["Describes how machine learning adjusts parameters from data to improve a measured result.","Compares machine learning, search on an objective and a distributed system on what each needs as input and what each guarantees.","States what each can and cannot be said to do without attributing intention to it."],"concepts":[{"id":"OE-CONCEPT-computational-core-machine-learning","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-search","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-distributed-system","emphasis":"primary"},{"id":"OE-CONCEPT-computational-core-model","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-feedback","emphasis":"reinforcing"},{"id":"OE-CONCEPT-computational-core-data","emphasis":"reinforcing"}],"required":true,"literature_ids":["OE-LITERATURE-wilensky-2020","OE-LITERATURE-tullis-goldstone-2017","OE-LITERATURE-grimm-etal-2020-odd","OE-LITERATURE-guest-2026-models","OE-LITERATURE-guest-martin-vanrooij-2026","OE-LITERATURE-guest-suarez-vanrooij-2025-cail","OE-LITERATURE-shiffrin-mitchell-2023","OE-LITERATURE-binz-schulz-2023","OE-LITERATURE-anwarzai-2026","OE-LITERATURE-falandays-2023","OE-LITERATURE-rahwan-2019-machine-behaviour","OE-LITERATURE-watson-szathmary-2016","OE-LITERATURE-kosal-2026"],"draft_note":"AI-drafted 2026-10-25 from the preparation note. No expert has reviewed it.","_source":{"repo":"computational-core-draft-2026-10-25","path":"strands/strand-c3-systems-models-and-learning-from-data.yaml"}}'::jsonb, 'accepted')
