  INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, status)
  VALUES
  ('d755f127-d8c9-54e2-b60e-e5129a50228e', v_project, v_branch, 'data-and-representation', $J$Data and Representation$J$, 'vertical', $J$Computing works on data that stands for things, and every representation keeps some detail and drops some. The strand builds from sorting and labelling to the limits of any representation.$J$, $J$The foundation strand. Students move from sorting and labelling things and learning that symbols stand for things, through recording and charting data and encoding text, images and numbers in binary, to the relation between information, compression and the limits of any representation.$J$, 'accepted'),
  ('a4cce988-5777-5693-a2aa-c1bd828b32a5', v_project, v_branch, 'algorithms-and-programs', $J$Algorithms and Programs$J$, 'vertical', $J$A program is an algorithm a machine can run, and it is right only against a specification. The strand builds from following steps to arguing that an algorithm is correct and comparing its efficiency.$J$, $J$The central strand. Students move from following and writing step-by-step instructions, through programs with sequences, loops and conditions, to decomposing problems, writing functions and testing against a specification, and finally arguing for an algorithm's correctness and comparing its efficiency with another.$J$, 'accepted'),
  ('bd5271ae-968e-53fc-8105-3e23777c399c', v_project, v_branch, 'systems-models-and-learning-from-data', $J$Systems, Models and Learning from Data$J$, 'vertical', $J$Systems made of many parts can be modelled and run, and some adjust themselves from data. The strand builds from machines that follow written rules to stating what machine learning, search and distributed systems can and cannot be said to do.$J$, $J$The macro strand. Students learn that machines follow rules people write, build simple models and simulations of everyday systems, build agent-based and feedback models where many simple rules produce one pattern, and compare machine learning, search and distributed systems. Its grounding is the strongest of the three strands in the corpus and its standards backing for search is the weakest.$J$, 'accepted')
  INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, relation_to_next)
  VALUES
